"use client";

import { Button as ButtonPrimitive } from "@base-ui/react/button";
import { cva } from "class-variance-authority";
import {
  type ButtonHTMLAttributes,
  cloneElement,
  forwardRef,
  isValidElement,
  type KeyboardEvent,
  type PointerEvent,
  type ReactElement,
  useCallback,
  useRef,
} from "react";
import { cn } from "../lib/cn.js";
import { animate, dur, ease, spring, useReducedMotion } from "../motion/index.js";

// Generated by shadcn (Base UI, Mira) and rewritten to the annotated-scoresheet tokens
// (packages/ui/DESIGN.md, "Interaction states"). Hover changes tone, never position (M5).
export const buttonVariants = cva(
  [
    "inline-flex shrink-0 items-center justify-center gap-2 whitespace-nowrap select-none",
    "rounded-field border font-sans font-medium",
    "transition-colors duration-(--dur-quick) ease-out",
    "focus-visible:outline-2 focus-visible:outline-offset-2 focus-visible:outline-ink",
    "disabled:pointer-events-none aria-disabled:pointer-events-none",
    "[&_svg]:pointer-events-none [&_svg]:shrink-0",
  ],
  {
    variants: {
      variant: {
        primary: [
          "border-ink bg-ink text-on-ink hover:border-ink-soft hover:bg-ink-soft",
          "disabled:border-well disabled:bg-well disabled:text-ink-faint",
        ],
        outline: [
          "border-rule-strong bg-transparent text-ink hover:bg-well",
          "active:bg-well active:shadow-[inset_0_0_0_1px_var(--color-rule-strong)]",
          "disabled:border-rule disabled:text-ink-faint",
        ],
        quiet: [
          "border-transparent bg-transparent text-ink-soft hover:bg-well hover:text-ink",
          "active:bg-well active:shadow-[inset_0_0_0_1px_var(--color-rule-strong)]",
          "disabled:text-ink-faint",
        ],
        danger: [
          "border-pen-text bg-transparent text-pen-text hover:bg-well",
          "active:bg-well disabled:border-rule disabled:text-ink-faint",
        ],
      },
      size: {
        sm: "h-8 px-3 text-sm [&_svg]:size-4",
        md: "h-10 px-4 text-base [&_svg]:size-5",
      },
    },
    defaultVariants: { variant: "primary", size: "md" },
  },
);

export interface ButtonProps extends ButtonHTMLAttributes<HTMLButtonElement> {
  variant?: "primary" | "outline" | "quiet" | "danger";
  size?: "sm" | "md";
  /** Render the single child element (a link, say) with the button's look and press. */
  asChild?: boolean;
}

const PRESS_SCALE = 0.97;

/**
 * The pen-press (choreography 7): scale 0.97 over `dur.instant`, released on `land` with its small
 * rebound. Transform only (M9). Under reduced motion there is no movement (M10).
 */
function usePenPress() {
  const reduced = useReducedMotion();
  const held = useRef(false);

  const press = useCallback(
    (el: HTMLElement) => {
      if (reduced || held.current) return;
      held.current = true;
      animate(el, { scale: PRESS_SCALE }, { duration: dur.instant, ease: [...ease.out] });
    },
    [reduced],
  );
  const release = useCallback((el: HTMLElement) => {
    if (!held.current) return;
    held.current = false;
    animate(el, { scale: 1 }, spring.land);
  }, []);
  return { press, release };
}

export const Button = forwardRef<HTMLButtonElement, ButtonProps>(function Button(
  {
    className,
    variant,
    size,
    asChild = false,
    children,
    onPointerDown,
    onPointerUp,
    onPointerLeave,
    onPointerCancel,
    onKeyDown,
    onKeyUp,
    ...props
  },
  ref,
) {
  const { press, release } = usePenPress();
  const classes = cn(buttonVariants({ variant, size }), className);

  const handlers = {
    onPointerDown: (e: PointerEvent<HTMLButtonElement>) => {
      onPointerDown?.(e);
      if (e.button === 0) press(e.currentTarget);
    },
    onPointerUp: (e: PointerEvent<HTMLButtonElement>) => {
      onPointerUp?.(e);
      release(e.currentTarget);
    },
    onPointerLeave: (e: PointerEvent<HTMLButtonElement>) => {
      onPointerLeave?.(e);
      release(e.currentTarget);
    },
    onPointerCancel: (e: PointerEvent<HTMLButtonElement>) => {
      onPointerCancel?.(e);
      release(e.currentTarget);
    },
    onKeyDown: (e: KeyboardEvent<HTMLButtonElement>) => {
      onKeyDown?.(e);
      if (!e.repeat && (e.key === " " || e.key === "Enter")) press(e.currentTarget);
    },
    onKeyUp: (e: KeyboardEvent<HTMLButtonElement>) => {
      onKeyUp?.(e);
      release(e.currentTarget);
    },
  };

  // asChild keeps the child's own element and role (a link stays a link), so it skips Base UI's
  // button behaviour and only takes the look and the press.
  if (asChild && isValidElement(children)) {
    const child = children as ReactElement<Record<string, unknown> & { className?: string }>;
    return cloneElement(child, {
      ...props,
      ...handlers,
      ref,
      "data-slot": "button",
      className: cn(classes, child.props.className),
    });
  }

  return (
    <ButtonPrimitive ref={ref} data-slot="button" className={classes} {...props} {...handlers}>
      {children}
    </ButtonPrimitive>
  );
});
